using System;
using System.Collections.Generic;
using UnityEngine;

// Portraits of known mod characters, shipped with the APK so leaderboard
// entries from modded runs show an icon even when the mod is not installed
// or is disabled. Keys are the character's "package:id" external ID.
public static class OpenBonkBundledCharacterIcons
{
    private static readonly Dictionary<string, string> Png = new Dictionary<string, string>(StringComparer.Ordinal)
    {
        // mods/pikachu/content/portrait.png
        ["pikachu:pikachu"] = "",
    };

    private static readonly Dictionary<string, Texture2D> Loaded = new Dictionary<string, Texture2D>(StringComparer.Ordinal);

    public static Texture2D Get(string externalId)
    {
        if (string.IsNullOrEmpty(externalId) || !Png.TryGetValue(externalId, out var data)) return null;
        if (Loaded.TryGetValue(externalId, out var cached)) return cached;
        Texture2D texture = null;
        try
        {
            texture = new Texture2D(2, 2, TextureFormat.RGBA32, false);
            if (!texture.LoadImage(Convert.FromBase64String(data))) { UnityEngine.Object.Destroy(texture); texture = null; }
        }
        catch (Exception e)
        {
            Debug.LogWarning("OpenBonk bundled icon " + externalId + ": " + e.GetType().Name);
            if (texture != null) UnityEngine.Object.Destroy(texture);
            texture = null;
        }
        Loaded[externalId] = texture;
        return texture;
    }
}
